/**
 * Topic vocabulary hints.
 * When the "提示詞彙" toggle is on, each examiner question (and the Part 2 cue
 * card) gets a short list of topic phrases and words, generated by a fast
 * text model through a normal generateContent call. The examiner's Live
 * session is not involved: it never sees the hints and still gives none aloud.
 * Needs the Gemini API key saved in Settings (server.py tokens only work for
 * the Live API).
 */

const HINT_MODEL = "gemini-3.5-flash-lite";
const HINT_TIMEOUT_MS = 15000;

// How many items to ask for in each part
const HINT_COUNTS = {
  1: { phrases: 4, words: 4 },
  2: { phrases: 6, words: 6 },
  3: { phrases: 5, words: 4 },
};

const HINT_SCHEMA = {
  type: "OBJECT",
  properties: {
    starter: {
      type: "STRING",
      description: "One opening sentence that paraphrases the question, with ... where the candidate fills in. Empty if there is no real question.",
    },
    phrases: {
      type: "ARRAY",
      items: {
        type: "OBJECT",
        properties: {
          en: { type: "STRING", description: "The phrase or collocation, including any preposition it needs" },
          zh: { type: "STRING", description: "Short meaning in Traditional Chinese (Taiwan)" },
          example: { type: "STRING", description: "A short first-person example sentence that answers the question" },
        },
        required: ["en", "zh", "example"],
      },
    },
    words: {
      type: "ARRAY",
      items: {
        type: "OBJECT",
        properties: {
          en: { type: "STRING" },
          zh: { type: "STRING", description: "Short meaning in Traditional Chinese (Taiwan)" },
        },
        required: ["en", "zh"],
      },
    },
  },
  required: ["starter", "phrases", "words"],
};

const HINT_INSTRUCTION = `You help an IELTS Speaking candidate from Taiwan who understands plenty of English but struggles to come up with topic-specific phrases while speaking. Given the examiner's latest question, suggest vocabulary the candidate can use in their own answer.

Rules:
- Natural spoken British English that fluent speakers really use, at about band 7. Prefer collocations, phrasal verbs and useful chunks over rare single words. No obscure or old-fashioned idioms.
- Every item must help answer this specific question from the candidate's own point of view.
- phrases: give the chunk with any preposition it needs (e.g. "devote time to something", "get into something"). Example sentences are first person, natural, and under 15 words.
- words: useful topic adjectives, nouns or verbs.
- starter: one opening sentence that paraphrases the question instead of just saying "Yes", for example "A hobby I'd love to try if I had more time is ...". Leave a "..." where the candidate fills in.
- Chinese meanings are short and in Traditional Chinese as used in Taiwan.
- Do not repeat the same phrase in two forms.
- If the examiner's words contain no real question to answer (a greeting, asking for the candidate's name or ID, instructions, or "Can you start speaking now?"), return an empty starter and empty lists.`;

function buildHintPrompt({ part, question, card, followsCard }) {
  const counts = HINT_COUNTS[part] || HINT_COUNTS[1];
  const lines = [`IELTS Speaking Part ${part || 1}.`];
  if (card) {
    lines.push(
      `Part 2 cue card: ${card.topic}`,
      "You should say:",
      ...(card.bullet_points || []).map((b) => `- ${b}`),
      card.final_point || "",
      "Suggest vocabulary that covers every point on the card, so the candidate can talk for two minutes."
    );
  } else {
    if (followsCard) lines.push(`This Part 3 discussion follows the Part 2 card "${followsCard}".`);
    lines.push(`The examiner just said: "${question}"`);
  }
  lines.push(`Give ${counts.phrases} phrases and ${counts.words} words.`);
  return lines.filter(Boolean).join("\n");
}

function cleanHints(raw) {
  const list = (v) => (Array.isArray(v) ? v : []);
  const text = (v) => String(v || "").trim();
  return {
    starter: text(raw.starter),
    phrases: list(raw.phrases)
      .map((p) => ({ en: text(p.en), zh: text(p.zh), example: text(p.example) }))
      .filter((p) => p.en),
    words: list(raw.words)
      .map((w) => ({ en: text(w.en), zh: text(w.zh) }))
      .filter((w) => w.en),
  };
}

/**
 * One generateContent call with a timeout. Also used by study.js.
 * Returns { text, candidate } where candidate holds e.g. groundingMetadata.
 * Errors carry `status` (the HTTP status) when the API refused the request.
 */
async function generateContent(model, request, apiKey, { signal, timeoutMs }) {
  const timeout = new AbortController();
  const timer = setTimeout(() => timeout.abort(), timeoutMs);
  const onAbort = () => timeout.abort();
  if (signal) signal.addEventListener("abort", onAbort);

  try {
    const response = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-goog-api-key": apiKey },
        signal: timeout.signal,
        body: JSON.stringify(request),
      }
    );
    const body = await response.json().catch(() => null);
    if (!response.ok) {
      const error = new Error(body?.error?.message || `HTTP ${response.status}`);
      error.status = response.status;
      throw error;
    }

    const candidate = body?.candidates?.[0] || {};
    const text = (candidate.content?.parts || []).map((p) => p.text || "").join("");
    if (!text) throw new Error("模型沒有回傳內容");
    return { text, candidate };
  } catch (error) {
    if (error.name === "AbortError") throw new Error(signal?.aborted ? "已取消" : "逾時");
    throw error;
  } finally {
    clearTimeout(timer);
    if (signal) signal.removeEventListener("abort", onAbort);
  }
}

/**
 * Generate hints for one question or cue card.
 * @param {{part:number, question?:string, card?:object, followsCard?:string}} request
 * @param {string} apiKey
 * @param {AbortSignal} [signal]
 */
async function fetchHints(request, apiKey, signal) {
  const { text } = await generateContent(
    HINT_MODEL,
    {
      systemInstruction: { parts: [{ text: HINT_INSTRUCTION }] },
      contents: [{ role: "user", parts: [{ text: buildHintPrompt(request) }] }],
      generationConfig: {
        temperature: 0.6,
        responseMimeType: "application/json",
        responseSchema: HINT_SCHEMA,
      },
    },
    apiKey,
    { signal, timeoutMs: HINT_TIMEOUT_MS }
  );
  return cleanHints(JSON.parse(text));
}
